update public.fields set verification_status='verified_against_standard', verification_quote='Die mit der Planung beauftragten Ingenieurbüros sollten die „Treiber“ von neuen, zukunftsorientierten und zukunftsfähigen Ansätzen sein. Im Gegenzug muss der Auftraggeber die Projekte so aufsetzen, dass dies auch möglich ist. Dabei ist es unerlässlich, dass ein Abgleich der Erwartungen beider Seiten zu einem zielgerichteten Miteinander führt. — printed p.10', verification_note='md-verified 2026-09-05 (§3 Grundsätze, printed p.10) [VC] — "sollten" — advisory', verified_at=now() where id='c7c40ef5-6937-4b6c-ba3c-c621fedaf00d' and verification_status not in ('verified_against_standard','corrected');

