update public.fields set verification_status='verified_against_standard', verification_quote='Die Gestaltungsspielräume, die das Vergabe- und Vertragsrecht für Innovationen bieten, sollten ausgeschöpft werden. Das strikte Kopieren und das erneute Verwenden von bereits durchgeführten Verfahrensweisen wird der Anforderung an einen wirtschaftlichen Betrieb eines Gesamtsystems zukünftig nicht mehr gerecht. Ein Umdenken ist erforderlich. — printed p.10', verification_note='md-verified 2026-09-05 (§3 Grundsätze, printed p.10) [VC]', verified_at=now() where id='3744a408-4ff4-45d8-a11e-f9f52e37fbad' and verification_status not in ('verified_against_standard','corrected');

