-- vorwort_indirect_cost_env_impact
update public.fields set verification_status='verified_against_standard', verification_quote='Direkte Kosten- und / oder Umweltauswirkungen sind durch dieses Merkblatt nicht zu erwarten. Die konsequente Umsetzung der Vorschläge aus den Merkblättern verbessert Projektabläufe, es gibt weniger Störungen, die Wirtschaftlichkeit der Projektabwicklung verbessert sich. Darüber hinaus kann in vielen Fällen eine Reduzierung der Lebenszykluskosten erwartet werden. — printed p.3', verification_note='md-verified 2026-09-05 (Vorwort, printed p.3) [VC]', verified_at=now() where id='921e9f36-e482-477a-840f-f1af06a05e89' and verification_status not in ('verified_against_standard','corrected');

