-- pz_62_1_status
update public.fields set verification_status='verified_against_standard', verification_quote='Die „Bedarfsplanung Projekt“ beschreibt die Anforderungen und Rahmenbedingungen so ausführlich und konkret, dass Bauherr und Planende in die Lage versetzt werden, ein gleiches Verständnis für die Projektaufgabe zu entwickeln und zu klären, welche Leistungen in Eigenleistung erbracht und welche Leistungen vergeben werden müssen. — printed p.14', verification_note='md-verified 2026-09-05 (§6.2 Phasenziele, printed p.14) [VC]', verified_at=now() where id='b60c1a1a-0115-4f77-925b-79fb4a9788f5' and verification_status not in ('verified_against_standard','corrected');

-- pz_62_2_status
update public.fields set verification_status='verified_against_standard', verification_quote='Wurde im Vorfeld ein Konzept für das Gesamtsystem erstellt (siehe 5.3), so sind die Ergebnisse in die Aufstellung der Bedarfsplanung für das Projekt zu integrieren. — printed p.14', verification_note='md-verified 2026-09-05 (§6.2 Phasenziele, printed p.14) [VC] — conditional ("Wurde im Vorfeld … erstellt")', verified_at=now() where id='db4d09b7-f9a7-4c22-bf43-b148bc6f58fd' and verification_status not in ('verified_against_standard','corrected');

-- pz_62_3_status
update public.fields set verification_status='verified_against_standard', verification_quote='Um einen aussagekräftigen und belastbaren Ingenieurvertrag zu schließen, sind alle erforderlichen Leistungen, unabhängig davon, ob Grundleistungen oder besondere Leistungen, erfasst. Beispielsweise sind die Anzahl der Objekt- und Fachplanungen, die Leistungsphasen, der Schwierigkeitsgrad, die Einbindung des Bestands und die besonderen Leistungen festzulegen. — printed p.14', verification_note='md-verified 2026-09-05 (§6.2 Phasenziele, printed p.14) [VC]', verified_at=now() where id='63166a42-7ed9-4d27-874c-a3cc9a4934d4' and verification_status not in ('verified_against_standard','corrected');

-- pz_62_4_status
update public.fields set verification_status='verified_against_standard', verification_quote='Die Anforderungen und Ziele sowie die Prioritäten zwischen Terminen, Kosten und Qualitäten sind definiert. Den Planenden sind die Ziele bekannt. Hierbei sind verfügbare Ressourcen und vorhandene Kapazitäten bei allen Projektbeteiligten (inklusive AG) berücksichtigt. Dies gilt auch für Methoden der digitalen Planung. — printed p.14', verification_note='md-verified 2026-09-05 (§6.2 Phasenziele, printed p.14) [VC]', verified_at=now() where id='38754206-9513-43c8-8f83-26ac8a2ba381' and verification_status not in ('verified_against_standard','corrected');

-- pz_62_5_status
update public.fields set verification_status='verified_against_standard', verification_quote='Die Projektmanagementstrukturen inklusive Kommunikations- und Entscheidungsstrukturen sind geklärt, kommuniziert und kalkulierbar. Verantwortlichkeiten und Kompetenzen sind geklärt. | Das Ergebnis ist eine dokumentierte und freigegebene projektbezogene Bedarfsplanung, die die formulierten Anforderungen und Ziele erreicht. — printed p.14', verification_note='md-verified 2026-09-05 (§6.2 Phasenziele, printed p.14) [VC]', verified_at=now() where id='a9264c77-609e-4d71-a074-5602d11db14c' and verification_status not in ('verified_against_standard','corrected');

