update public.fields set verification_status='verified_against_standard', verification_quote='Unter Projektkommunikation wird der Einsatz von Kommunikationsplattformen verstanden. Beim Einsatz der BIM-Planung stehen dafür Werkzeuge bereit und werden eingesetzt. | Schnittstellen zwischen der rein digitalen Kommunikation (bspw. über das BIM-Modell) und der Kommunikation in Planungs- und Baubesprechungen sind geklärt. — printed p.21', verification_note='md-verified 2026-09-05 (§7.5.2 Projektkommunikation, Ziele, printed p.21) [VC] — "Beim Einsatz der BIM-Planung" — conditional on BIM use', verified_at=now() where id='4d1aa5db-2849-48d2-85ef-196f1d6dc0ab' and verification_status not in ('verified_against_standard','corrected');

-- cde_used_for_communication
update public.fields set verification_status='verified_against_standard', verification_quote='Eine CDE-BIM-Plattform als Kommunikationsplattform ist eingerichtet und wird genutzt. Die Sprachkommunikation findet gegebenenfalls über Videokonferenzsysteme statt. — printed p.21', verification_note='md-verified 2026-09-05 (§7.5.2 Projektkommunikation, Ziele, printed p.21) [VC] — conditional on BIM use (§7.5.2 "Beim Einsatz der BIM-Planung")', verified_at=now() where id='b2467ccc-0947-4a60-8bcd-9874a7b2d846' and verification_status not in ('verified_against_standard','corrected');

-- public_info_via_digital_media
update public.fields set verification_status='verified_against_standard', verification_quote='Eine vorausschauende Projektkommunikation fördert im Allgemeinen bei den Stakeholdern das Verständnis und die Akzeptanz für das Projekt. | Betroffene erhalten über geeignete digitale Medien (bspw. Projektwebsite) Zugang zu den für sie wichtigen Informationen. — printed p.21', verification_note='md-verified 2026-09-05 (§7.5.3 Information von Bürgern und Betroffenen, Ziele, printed p.21) [VC] — "bspw. Projektwebsite" — example', verified_at=now() where id='60d02129-2c97-4fec-a191-08d06c4ea57c' and verification_status not in ('verified_against_standard','corrected');

-- communication_concept_adaptive
update public.fields set verification_status='verified_against_standard', verification_quote='Die Kommunikationsmittel sind individuell auf ein Projekt zugeschnitten und individuell einzusetzen. Sie dienen der Kommunikation nach außen wie auch der projektinternen Kommunikation. | Ein Kommunikationskonzept ist erarbeitet, welches nicht starr ist, sondern sich dem Projektverlauf anpasst und an den Projektphasen des Projekts orientiert. — printed p.21', verification_note='md-verified 2026-09-05 (§7.5.3 Information von Bürgern und Betroffenen, Ziele, printed p.21) [VC]', verified_at=now() where id='681d5616-4491-47a2-a069-b9e73bd54a66' and verification_status not in ('verified_against_standard','corrected');

